from src.nodes.base import BaseNode
from src.runtime.lookdev import get_material_assignment_engine
import json

class Hou_Mcp_Material_Assign(BaseNode):
    name = "hou_mcp_material_assign"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("assets_json", "string", widget_type="text", default="[]")
        self.add_input("renderer",    "string", widget_type="text", default="usd_preview_surface")
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("plan_json",      "string")
        self.add_output("total_assigned", "int")
        self.add_output("plan_ok",        "bool")

    async def execute(self, inputs):
        assets_json = str(inputs.get("assets_json", "[]") or "[]")
        renderer    = str(inputs.get("renderer",    "usd_preview_surface") or "usd_preview_surface")
        try:
            asset_list = json.loads(assets_json)
            if not isinstance(asset_list, list):
                asset_list = []
        except Exception as exc:
            self.log_error(f"Failed to parse assets_json: {exc}")
            return {"plan_json": "{}", "total_assigned": 0, "plan_ok": False, "exec_out": True}
        try:
            engine = get_material_assignment_engine()
            plan = engine.generate_assignment_plan(asset_list, renderer)
            self.log_info(f"Assignment plan: {plan.total_assigned}/{plan.total_assets} assets assigned (ok={plan.ok}).")
            return {
                "plan_json":      json.dumps(plan.to_dict(), sort_keys=True, default=str),
                "total_assigned": plan.total_assigned,
                "plan_ok":        plan.ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Material assignment failed: {exc}")
            return {"plan_json": "{}", "total_assigned": 0, "plan_ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Material_Assign
